entries[14517] = { ["name"] = "Kreuzfahrerstoß", ["text"] = "40 Mana Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nFügt einem Gegner 60% des normalen Waffenschadens zu und erhöht seinen erlittenen Heiligschaden pro Anwendung von 'Kreuzfahrerstoß' um 10. Bis zu 5-mal stapelbar. Hält 15 Sek. lang an." }
