entries[14807] = { ["name"] = "Großer Magiezauberstab", ["text"] = "Wirken in 1.5 sek.\nTools: Runenverzierte Kupferrute\nReagenzien:\nEinfaches Holz , Große Magieessenz\nLässt einen großen Magiezauberstab entstehen.\nGroßer Magiezauberstab\nWird beim Anlegen gebunden\nDistanz Zauberstab\n5 - 11 Schaden Tempo 1.80 + 5 - 11 Arkanschaden\n(8.89 Schaden pro Sekunde)\n+2 Intelligenz\nHaltbarkeit 55 / 55\n13" }
entries[14809] = { ["name"] = "Geringer Mystikerzauberstab", ["text"] = "Wirken in 1.5 sek.\nTools: Runenverzierte Kupferrute\nReagenzien:\nSternenholz , Geringe Mystikeressenz , Seelenstaub\nLässt einen geringen Mystikerzauberstab entstehen.\nGeringer Mystikerzauberstab\nWird beim Anlegen gebunden\nDistanz Zauberstab\n10 - 19 Schaden Tempo 1.80 + 10 - 19 Arkanschaden\n(16.11 Schaden pro Sekunde)\n+4 Ausdauer\n+3 Intelligenz\nHaltbarkeit 75 / 75\n26" }
entries[14810] = { ["name"] = "Großer Mystikerzauberstab", ["text"] = "Wirken in 1.5 sek.\nTools: Runenverzierte Kupferrute\nReagenzien:\nSternenholz , Große Mystikeressenz , Visionenstaub\nLässt einen großen Mystikerzauberstab entstehen.\nGroßer Mystikerzauberstab\nWird beim Anlegen gebunden\nDistanz Zauberstab\n12 - 24 Schaden Tempo 2.00 + 12 - 24 Arkanschaden\n(18.00 Schaden pro Sekunde)\n+4 Ausdauer\n+4 Intelligenz\nHaltbarkeit 75 / 75\n30" }
