entries[14875] = { ["name"] = "Fluch der Pein", ["text"] = "75 Mana 30 Meter Reichweite\nSofort\nVerflucht einen Feind mit Pein und fügt 15 Sek. lang alle 3 Sek. Schattenschaden zu. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[14887] = { ["name"] = "Schattenblitzsalve", ["text"] = "160 Mana 30 Meter Reichweite\nWirken in 3 sek.\nSchleudert Geschosse von dunkler Magie auf in der Nähe befindliche Feinde und verursacht Schattenschaden." }
