entries[14890] = { ["name"] = "Abwerfender Draufschlag", ["text"] = "30 Meter Reichweite\nSofort\nZwingt einen Feind abzusitzen." }
entries[14891] = { ["name"] = "Dunkeleisen verhütten", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nDunkeleisenerz (8)\nErmöglicht dem Minenarbeiter, Brocken von Dunkeleisenerz zu einem Dunkeleisenbarren zu verhütten. Dunkeleisen kann nur in der schwarzen Schmiede in den Schwarzfelstiefen verhüttet werden.\nDunkeleisenbarren" }
entries[14894] = { ["name"] = "Dunkeleisen verhütten" }
entries[14895] = { ["name"] = "Überwältigen", ["text"] = "Nahkampfreichweite\nSofort 5 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nWaffen ( Hotfix - Passivfähigkeit )\nÜberwältigt einen Feind sofort und verursacht Waffenschaden plus 35. Kann nur verwendet werden, nachdem das Ziel ausgewichen ist. Auf 'Überwältigen' kann nicht mit 'Blocken', 'Ausweichen' oder 'Parieren' reagiert werden.\n\nFuror, Schutz\nÜberwältigt einen Feind sofort und verursacht Waffenschaden plus 15. Kann nur verwendet werden, nachdem das Ziel ausgewichen ist. Auf 'Überwältigen' kann nicht mit 'Blocken', 'Ausweichen' oder 'Parieren' reagiert werden." }
entries[14897] = { ["name"] = "Verlangsamendes Gift", ["text"] = "30 Meter Reichweite\nSofort\nErhöht die Zeit zwischen Angriffen eines Feindes um 25% und verlangsamt sein Bewegungstempo um 30%. Hält 8 Sek. lang an." }
entries[14900] = { ["name"] = "Kettenheilung", ["text"] = "150 Mana 40 Meter Reichweite\nWirken in 2.5 sek.\nErfüllt einen verwundeten Verbündeten mit Heilenergie, die sich auf einen anderen in der Nähe befindlichen Verbündeten ausbreitet. Der Zauber wirkt sich auf bis zu 3 Ziele aus, aber die Heilenergie wird bei jedem folgenden Ziel um 50% reduziert." }
