entries[14903] = { ["name"] = "Blutung", ["text"] = "25 Energie Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nFügt einem Feind alle 2 Sek. körperlichen Schaden zu. Zusätzliche Combopunkte erhöhen den in regelmäßigen Abständen zugefügten Schaden und die Gesamtdauer." }
