entries[15286] = { ["name"] = "Vampirumarmung", ["text"] = "Sofort 3 min Abklingzeit\nDie Umarmung der Schattenenergie umschlingt Euch. Wenn Ihr mittels Eurer Einzelzielzauber Schaden verursacht, werdet Ihr und Eure Verbündeten um 50% des von Euch verursachten Schattenschadens geheilt. Diese Heilung wird gleichmäßig unter allen Zielen aufgeteilt. Hält 15 Sek. lang an." }
