entries[15292] = { ["name"] = "Dunkeleisenpulverisierer", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nDunkeleisenbarren (18), Herz des Feuers (4)\nDunkeleisenpulverisierer\nWird beim Anlegen gebunden\nZweihändig Streitkolben\n140 - 211 Schaden Tempo 3.70\n(47.43 Schaden pro Sekunde)\nHaltbarkeit 100 / 100\n50\nTrefferchance: Betäubt ein Ziel 8 Sek. lang." }
entries[15293] = { ["name"] = "Dunkeleisenpanzer", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nDunkeleisenbarren (10), Herz des Feuers (2)\nDunkeleisenpanzer\nWird beim Anlegen gebunden\nBrust Kette\n386 Rüstung\n+21 Beweglichkeit\n+14 Ausdauer\nErhöht Eure kritische Trefferwertung um + 14.\nHaltbarkeit 135 / 135\n51" }
entries[15294] = { ["name"] = "Dunkeleisenzerreißer", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nDunkeleisenbarren (26), Herz des Feuers (4)\nDunkeleisenzerreißer\nWird beim Anlegen gebunden\nZweihändig Axt\n101 - 153 Schaden Tempo 2.60\n(48.85 Schaden pro Sekunde)\nHaltbarkeit 100 / 100\n52\nTrefferchance: Verringert die Rüstung des Ziels 20 Sek. lang um 382 ." }
