entries[15783] = { ["name"] = "Blizzard", ["text"] = "8 Mana 30 Meter Reichweite\nWirken in 2 sek.\nRuft einen Blizzard herbei, der 10 Sek. lang anhält und Feinden im ausgewählten Gebiet alle 2 Sek. 6 Frostschaden zufügt." }
entries[15784] = { ["name"] = "Frostrüstung", ["text"] = "10 Mana 20 Meter Reichweite\nSofort\nUmgibt einen Verbündeten mit einer Frostschicht, die 1 Min. lang bestehen bleibt. Das dicke Eis erhöht die Rüstung um 12, verlangsamt das Bewegungstempo von Nahkampfangreifern um 20% und erhöht die Zeit zwischen ihren Angriffen um 30%." }
